#include "overlapping.h"

void Overlapping(double *result, int epsilon[N]) {
    const int M = 1032;
    const int PATTERN_LEN = 9;
    const int NUM_BLOCKS = N / M; // 1024

    unsigned int nu[6] = {0,0,0,0,0,0};

    const double pi[6] = {
        0.13533528323661269,
        0.27067056647322538,
        0.27067056647322538,
        0.18044704431548359,
        0.09022352215774179,
        0.05265301734371116
    };

    // Process each block
    for (int b = 0; b < NUM_BLOCKS; b++) {
        int base = b * M;
        unsigned int shift_reg = 0;
        int match_count = 0;

        // Slide a 9-bit window through the block
        for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
            shift_reg = ((shift_reg << 1) | (unsigned int)epsilon[base + i]) & 0x1FF;
            if (i >= (PATTERN_LEN - 1)) {
                if (shift_reg == 0x1FF) {
                    match_count++;
                }
            }
        }

        if (match_count <= 4) {
            nu[match_count]++;
        } else {
            nu[5]++;
        }
    }

    // Compute chi-square statistic
    double chi2 = 0.0;
    for (int i = 0; i < 6; i++) {
#pragma HLS UNROLL
        double expected = (double)NUM_BLOCKS * pi[i];
        double diff = (double)nu[i] - expected;
        chi2 += (diff * diff) / expected;
    }

    *result = chi2;
}
```

